SELECT "nct", "author", "year", "pubmed_id", "total_sample_size" FROM public."clinical_trials" WHERE "cancer_type" ILIKE '%Melanoma%' AND "treatment_regimen" ILIKE '%Ipilimumab%' AND "combination_type" = 'ICI + ICI' OR "combination_type" = 'ICI + Chemo' OR "combination_type" = 'ICI + TKI' OR "combination_type" = 'ICI + MEKi' OR "combination_type" = 'ICI + Anti-VEGF' OR "combination_type" = 'ICI + Radiation' OR "combination_type" = 'ICI + Vaccine' OR "combination_type" = 'ICI + BRAFi + MEKi' OR "combination_type" = 'ICI + Chemo + Anti-VEGF' OR "combination_type" = 'ICI + ICI + Chemo'